document.addEventListener('keydown',e=>{const t=e.target.closest('[role=tab]');if(!t||!['ArrowLeft','ArrowRight','ArrowUp','ArrowDown','Home','End'].includes(e.key))return;const tabs=[...t.parentElement.querySelectorAll('[role=tab]')];let i=tabs.indexOf(t);i=e.key==='Home'?0:e.key==='End'?tabs.length-1:(i+(['ArrowLeft','ArrowUp'].includes(e.key)?-1:1)+tabs.length)%tabs.length;e.preventDefault();tabs[i].focus();tabs[i].click();});
